SELECT id, channel, ends_on, AVG(discount_pct) OVER (PARTITION BY channel ORDER BY ends_on ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS discount_pct_avg_6, SUM(discount_pct) OVER w_running AS cumulative_discount_pct, RANK() OVER (PARTITION BY promo_code ORDER BY discount_pct DESC) AS discount_pct_rank FROM promotions WINDOW w_running AS (PARTITION BY channel ORDER BY starts_on ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
